/// Diffs the Dart Whisper encoder output against `/tmp/whisper_enc_ref.raw`
/// (generated by scripts/whisper_encoder_reference.py).
library;

import 'dart:io';
import 'dart:typed_data';

import 'package:dart_pytorch/core/audio/whisper_mel.dart';
import 'package:dart_pytorch/core/nn/whisper.dart';
import 'package:dart_pytorch/core/nn/whisper_hf_loader.dart';
import 'package:dart_pytorch/core/tensor/tensor.dart';

Future<void> main() async {
  const wavPath = 'models/silero_vad/warmup_audio.wav';
  const weightsPath = 'models/whisper-tiny.en/model.safetensors';
  const refPath = '/tmp/whisper_enc_ref.raw';

  final mel = await WhisperMel().logMelFromFile(wavPath);
  final melT = Tensor.fromFloat32List([1, 80, 3000], mel, device: Device.CPU);

  final enc = WhisperEncoder(
    nMels: 80,
    embedDim: 384,
    numHeads: 6,
    numLayers: 4,
  );
  WhisperHFLoader.loadFile(enc, weightsPath);

  print('running forward pass…');
  final sw = Stopwatch()..start();
  final hidden = enc(melT);
  sw.stop();
  print('  ${sw.elapsedMilliseconds} ms → shape ${hidden.shape}');

  final ours = hidden.toList();
  final refBytes = File(refPath).readAsBytesSync();
  final ref = Float32List.view(
    refBytes.buffer,
    refBytes.offsetInBytes,
    refBytes.lengthInBytes ~/ 4,
  );

  if (ref.length != ours.length) {
    stderr.writeln('length mismatch: ref=${ref.length} vs ours=${ours.length}');
    exit(2);
  }

  double maxAbs = 0.0;
  double sumAbs = 0.0;
  int over1e2 = 0, over1e1 = 0, over5e_1 = 0;
  double sumOur = 0.0, sumRef = 0.0;
  double sqDiff = 0.0;
  int iMax = 0;
  for (int i = 0; i < ref.length; i++) {
    final d = (ours[i] - ref[i]).abs();
    sumAbs += d;
    sqDiff += d * d;
    if (d > maxAbs) {
      maxAbs = d;
      iMax = i;
    }
    if (d > 1e-2) over1e2++;
    if (d > 1e-1) over1e1++;
    if (d > 5e-1) over5e_1++;
    sumOur += ours[i];
    sumRef += ref[i];
  }
  final n = ref.length;
  print('N              = $n');
  print('mean abs diff  = ${(sumAbs / n).toStringAsFixed(6)}');
  print(
    'rms diff       = ${(sumAbs == 0 ? 0.0 : (sqDiff / n)).toStringAsFixed(9)}',
  );
  print(
    'max abs diff   = ${maxAbs.toStringAsFixed(4)}  at i=$iMax  ours=${ours[iMax].toStringAsFixed(4)}  ref=${ref[iMax].toStringAsFixed(4)}',
  );
  print(
    '# > 1e-2       = $over1e2 (${(100.0 * over1e2 / n).toStringAsFixed(3)}%)',
  );
  print(
    '# > 1e-1       = $over1e1 (${(100.0 * over1e1 / n).toStringAsFixed(3)}%)',
  );
  print(
    '# > 5e-1       = $over5e_1 (${(100.0 * over5e_1 / n).toStringAsFixed(3)}%)',
  );
  print('sum(ours)      = ${sumOur.toStringAsFixed(4)}');
  print('sum(ref)       = ${sumRef.toStringAsFixed(4)}');
}
